 function notifyError(message,conflict=false){const el=document.querySelector('#t-dialog-error')||document.querySelector('#t-page-error');if(el){el.hidden=false;el.innerHTML=esc(message)+(conflict?B('reload','Load latest project'):'');el.scrollIntoView({block:'nearest'})}bridge.toast(message)}
 function close(force=false,{restoreFocus=true}={}){const el=document.querySelector('.t-dialog');if(!el)return;if(dirty&&!force){el.querySelector('.t-discard').hidden=false;el.querySelector('[data-t-action=keep]')?.focus();return}closeDialog(el,{restoreFocus});dirty=false}
