 function editNeeds(id,{wording={}}={}){const a=component(project(),id);if(!a)return;const ns=needsFor(project(),id);dialog('Technology needs · '+a.ref,'<p>'+esc(a.title)+'</p><div class="t-source-brief"><span class="eyebrow">Application needs from Chapter 5</span><p>'+esc(a.technologyNeeds||'No technology needs recorded yet.')+'</p><a href="/?chapter=5&object='+esc(id)+'">Review the application boundary →</a></div><form id="t-needs-form">'+recordField('technology.needs','boundaryId',model().applicationBoundaries[id]||'',{options:[['','Not stated yet'],...boundaries()]})+'<p class="l-note">Keep each need you agree with and edit its words. A need you untick is removed with its support mappings.</p><input type="hidden" name="keep" value="">'+ns.map(n=>'<section class="t-need-editor"><label class="l-checkbox"><input type="checkbox" name="keep" value="'+esc(n.id)+'" checked>'+esc(n.id+' · '+categoryName(n.category))+(needIsSeed(project(),n)?' · proposed by AIW':'')+'</label><div>'+recordField('technology.needs','need',wording[n.id]??(n.description||''),{item:n.id,label:'Need'})+(wording[n.id]!=null?'<p class="l-note" data-t-wording="'+esc(n.id)+'">Wording from the drivers that reach '+esc(a.ref)+'; save to accept it, or edit it first.</p>':'')+recordField('technology.needs','criticality',n.criticality??'',{options:CRITICALITY,item:n.id})+recordField('technology.needs','grounds',groundText(n),{item:n.id})+'</div></section>').join('')+'<section class="t-need-editor">'+recordField('technology.needs','newCategory','',{options:[['','No new need'],...TECHNOLOGY_CATEGORIES]})+recordField('technology.needs','newNeed','')+recordField('technology.needs','newCriticality','',{options:CRITICALITY})+'</section><label class="l-checkbox"><input type="checkbox" name="confirmed"'+checked(ns.length&&ns.every(n=>n.confirmed&&!needChanged(project(),n)))+'>I reviewed these needs against the current application.</label>'+actions('Save application needs')+'</form>','needs',{id})}
 // AIW's proposals (round 12, D-13, DM-17): kept as the person's, or dismissed with a reason; a retired need restored.
