 function proposalsHTML(){const p=project(),seeds=technologySeeds(p),bounds=boundarySeeds(p),gone=retiredOf(p,'technology.needs');if(!seeds.length&&!bounds.length&&!gone.length)return '';const groups=components(p).map(a=>({a,needs:seeds.filter(n=>n.applicationId===a.id)})).filter(x=>x.needs.length);return '<section class="t-proposals"><h3>Proposed technology needs</h3><p>Review needs by component. Keeping a proposal makes it a draft in this project; it does not confirm its source, quality target or suitability.</p>'+groups.map(({a,needs})=>'<section data-need-component="'+esc(a.id)+'"><div class="needs-review-scroll"><table class="needs-review-table"><caption>'+esc(a.ref+' · '+a.title)+'</caption><thead><tr><th>Keep</th><th>Capability need</th><th>Statement</th><th>State</th><th>Dismiss</th></tr></thead><tbody>'+needs.map(n=>'<tr><td><input type="checkbox" data-need-id="'+esc(n.id)+'" checked aria-label="Keep '+esc(n.id)+'"></td><th scope="row">'+esc(categoryName(n.category))+'</th><td>'+esc(n.description)+'</td><td data-need-state>Proposed · unreviewed</td><td>'+B('dismiss-seed','Dismiss','',{'data-t-id':n.id,'aria-label':'Dismiss '+n.id})+'</td></tr>').join('')+'</tbody></table></div><div class="l-model-actions">'+B('keep-component-needs','Keep selected proposed needs','',{'data-t-id':a.id})+B('keep-seed','Keep all proposed for this component','',{'data-t-id':needs.map(n=>n.id).join(' ')})+B('needs','Review and edit needs','',{'data-t-id':a.id})+'</div></section>').join('')+(bounds.length?'<details><summary>Proposed trust boundaries · '+bounds.length+'</summary>'+bounds.map(b=>'<p>'+esc(b.ref+' · '+b.title)+' '+B('keep-seed','Keep as draft','',{'data-t-id':b.id})+' '+B('dismiss-seed','Dismiss','',{'data-t-id':b.id})+'</p>').join('')+'</details>':'')+(gone.length?'<details><summary>Retired needs · '+gone.length+'</summary>'+gone.map(x=>'<p>'+esc(x.id+' · '+categoryName(x.record.category)+' · '+x.reason)+' '+B('restore-seed','Restore','',{'data-t-id':x.id})+'</p>').join('')+'</details>':'')+'</section>';}
 function capabilityForm(c,ghost=false){
  const maps=c.mappings||supports(project(),c.id),extra=ghost?'<div class="l-before-after"><div><small>Why this proposal</small><p>'+esc(proposal.reason)+'</p></div><div><small>Reviewable change</small><p>'+esc(proposal.effect)+'</p></div></div>':'';
  return extra+'<form id="t-capability-form"><nav class="l-steps" aria-label="Capability editing steps">'+['Definition','Support & rationale','Continuity'].map((title,i)=>B('step',title,i===0?'active':'',{'data-t-step':i,'aria-pressed':i===0})).join('')+'</nav>'+
  '<section data-t-panel="0">'+fCapability('title',c.title)+'<div class="l-form-grid">'+fCapability('category',c.category,{options:TECHNOLOGY_CATEGORIES})+fCapability('owner',c.owner)+'</div>'+fCapability('purpose',c.purpose)+fCapability('boundary',c.boundary)+fCapability('boundaryId',c.boundaryId,{options:boundaries()})+'<p class="l-note">Describe the required service and behaviour. Products, versions, sizing, and runtime placement belong in Chapter 7.</p>'+B('step','Next: support & rationale','',{'data-t-step':1})+'</section>'+
  '<section data-t-panel="1" hidden><fieldset class="l-checks"><legend>Application needs supported</legend><p class="l-note">Each mapping retains its own reference. All mapped capabilities are required for that need; declare alternate paths in the capability’s continuity arrangement. Requirements and quality rationale are inherited through the application.</p>'+components(project()).map(a=>'<details class="t-map-group"'+(needsFor(project(),a.id).some(n=>maps.some(m=>m.needId===n.id))?' open':'')+'><summary>'+esc(a.ref)+' · '+esc(a.title)+'</summary>'+needsFor(project(),a.id).map(n=>{const m=maps.find(m=>m.needId===n.id);return '<div class="t-map-choice"><label><input type="checkbox" name="needIds" value="'+esc(n.id)+'"'+checked(m)+'><span><b>'+esc(n.id)+' · '+esc(categoryName(n.category))+'</b><small>'+esc(n.description)+'</small></span></label><div data-t-scope="'+esc(n.id)+'"'+(m?'':' hidden')+'>'+fCapability('scope',m?.scope||n.description,{item:n.id,label:'Support scope for '+n.id})+'</div></div>';}).join('')+'</details>').join('')+'</fieldset>'+fCapability('rationale',c.rationale)+fCapability('source',c.source)+fCapability('grounds',groundText(c))+'<details><summary>Additional quality drivers and decisions</summary><p class="l-note">Inherited references do not need re-entry. Add only the extra drivers or decisions relevant to this capability.</p>'+fCapability('driverIds',c.driverIds||[],{options:project().quality.drivers.map(d=>({id:d.id,title:d.id+' · '+d.title,note:targetText(d)+' · '+(d.targetConfirmed?'Confirmed':'Target assumption')}))})+fCapability('decisionIds',c.decisionIds||[],{options:project().decisions.records.map(d=>({id:d.id,title:d.id+' · '+d.question,note:decisionCurrent(project(),d)?'Architect accepted':'Draft / requires review'}))})+'</details>'+B('step','Next: continuity','',{'data-t-step':2})+'</section>'+
  '<section data-t-panel="2" hidden><div class="l-form-grid">'+fCapability('failureDomain',c.failureDomain)+fCapability('continuity',c.continuity??'',{options:[['','Not stated'],['single','Single support path'],['redundant','Independent alternate path'],['bypass','Safe degraded bypass']]})+'</div>'+fCapability('alternateDomain',c.alternateDomain)+fCapability('continuityPlan',c.continuityPlan)+fCapability('recoveryPlan',c.recoveryPlan)+fCapability('recoveryOwner',c.recoveryOwner)+'<div class="l-form-grid">'+fCapability('recoveryMinutes',c.recoveryMinutes)+fCapability('lossMinutes',c.lossMinutes)+'</div>'+fCapability('driverId',c.driverId||'',{options:driverOptions(project())})+'<label class="l-checkbox"><input type="checkbox" name="targetsConfirmed"'+checked(c.targetsConfirmed)+'>These recovery targets have been confirmed against evidence.</label>'+fCapability('assumptions',c.assumptions)+'<label class="l-checkbox"><input type="checkbox" name="assumptionsResolved"'+checked(c.assumptionsResolved)+'>I reviewed and resolved these assumptions.</label>'+(ghost?'<div class="t-proposed-deps">'+proposal.dependencies.map(d=>'<p><b>Proposed dependency:</b> '+esc(label(d.from))+' → '+esc(label(d.to))+'<br>'+esc(d.label)+' · '+esc(d.policy)+'</p>').join('')+'</div><label class="l-checkbox"><input type="checkbox" name="reviewed" required>I reviewed the capability, support mappings, and proposed dependencies.</label>':fCapability('status',c.status,{options:[['draft','Working draft'],['candidate','Candidate design'],['reviewed','Design reviewed']]}))+'<p class="l-note">Design review does not approve products, prove failover, or confirm upstream decisions.</p></section>'+ (ghost?B('preview-edits','Preview these edits on the model'):'')+actions(ghost?'Accept reviewed proposal':c.id?'Preview impact':'Save capability')+'</form>';
 }
 function step(index){const form=document.querySelector('#t-capability-form');if(!form)return;form.querySelectorAll('[data-t-panel]').forEach(p=>p.hidden=Number(p.dataset.tPanel)!==index);form.querySelectorAll('[data-t-step]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.tStep)===index);b.setAttribute('aria-pressed',String(Number(b.dataset.tStep)===index))});form.querySelector('[data-t-panel="'+index+'"] input,[data-t-panel="'+index+'"] select,[data-t-panel="'+index+'"] textarea')?.focus()}
 const blankCapability=()=>({category:'compute',title:'',purpose:'',boundary:'',owner:'',rationale:'',source:'',boundaryId:'tb-002',failureDomain:'',continuity:'',status:'draft',driverIds:[],decisionIds:[],mappings:[]});
 function editCapability(id,initial=0,draft){const pending=window.aiwInterfaceImpact?.commandFor('technology.capability',id);const c=draft||(pending?{...record(id),...pending.payload}:null)||record(id)||blankCapability();dialog(c.id?'Edit '+c.ref+' · '+c.title:'New logical technology capability',capabilityForm(c),'capability',{id:c.id});step(initial)}
 function readCapability(form){const fd=new FormData(form),raw=Object.fromEntries(fd);raw.driverIds=fd.getAll('driverIds');raw.decisionIds=fd.getAll('decisionIds');raw.mappings=fd.getAll('needIds').map(needId=>({needId,scope:String(fd.get('scope:'+needId)||'')}));raw.targetsConfirmed=fd.has('targetsConfirmed');raw.assumptionsResolved=fd.has('assumptionsResolved');raw.reviewed=fd.has('reviewed');Object.assign(raw,groundsOf(raw.grounds));delete raw.grounds;return raw}
 function editDependency(id,sourceId){const d=model().dependencies.find(d=>d.id===id)||{from:record(sourceId)?.id||records()[0]?.id,to:'',type:'dependency',critical:true};const options=logicalGraph(project()).nodes.filter(n=>['physical','technology','data'].includes(n.layer)).map(n=>[n.id,(n.ref||n.layer)+' · '+n.title]);dialog(d.id?'Edit '+d.id+' dependency':'Connect the technology model','<form id="t-dependency-form"><div class="l-form-grid">'+fDependency('from',d.from,{options:options})+fDependency('to',d.to,{options:[['','Select an object'],...options]})+'</div>'+fDependency('type',d.type,{options:DEPENDENCY_TYPES})+fDependency('label',d.label)+fDependency('policy',d.policy)+'<label class="l-checkbox"><input type="checkbox" name="critical"'+checked(d.critical)+'>For a required-service or trust link, failure of the “To” capability blocks the “From” capability.</label><p class="l-note">Data movement shows direction. Recovery links show what is needed to restore service. Neither automatically propagates an outage. Application support is edited through capability mappings.</p>'+actions('Save dependency')+'</form>','dependency',{id:d.id})}
 function editBoundary(id){const b=model().boundaries.find(b=>b.id===id)||{};dialog(b.id?'Edit '+b.ref+' trust boundary':'New trust boundary','<form id="t-boundary-form">'+recordField('technology.boundary','title',b.title)+recordField('technology.boundary','owner',b.owner)+recordField('technology.boundary','policy',b.policy)+actions('Save trust boundary')+'</form>','boundary',{id:b.id})}
 function graph(){
  const g=logicalGraph(project());
  if(proposal){const c=proposal.record,id=c.id||'t-ghost',node={id,ref:c.ref,layer:'technology',col:2,title:c.title,sub:'Reviewable ghost',description:c.purpose,ghost:true,attrs:{Capability:c.category,Boundary:c.boundary,Continuity:c.continuity,State:'Unsaved proposal'}};const i=g.nodes.findIndex(n=>n.id===id);if(i<0)g.nodes.push(node);else g.nodes[i]=node;
   g.edges=g.edges.filter(e=>!(e.techKind==='support'&&e.to===id));for(const m of proposal.mappings){const n=model().needs.find(n=>n.id===m.needId);if(n)g.edges.push({id:'ghost-'+n.id,from:n.applicationId,to:id,label:'would support '+n.id,kind:'trace',techKind:'support',ghost:true})}g.edges.push(...proposal.dependencies.map((d,i)=>({...d,id:'ghost-dep-'+i,kind:'trace',techKind:d.type,ghost:true})));
  }
  if(view!=='all'){const wanted={support:['support','dependency'],data:['data'],trust:['trust'],resilience:['resilience','dependency']}[view];g.edges=g.edges.filter(e=>!e.techKind||wanted.includes(e.techKind)||e.ghost);}
  if(simulation&&simulationStep>=0){const cs=simulation.capabilities.filter(c=>simulationStep>=1||(simulation.mode==='capability'?c.id===simulation.capabilityId:record(c.id)?.failureDomain.trim().toLowerCase()===simulation.failedDomain?.trim().toLowerCase())),apps=simulationStep>=1?simulation.applications:[];g.nodes=g.nodes.map(n=>{const hit=cs.find(c=>c.id===n.id)||apps.find(a=>a.id===n.id);return {...n,impact:hit?hit.state:''}});g.edges=g.edges.map(e=>({...e,impact:simulationStep>=1&&['support','dependency','trust'].includes(e.techKind)&&([...cs,...apps].some(x=>x.id===e.from)&&[...cs,...apps].some(x=>x.id===e.to))?'affected':''}));}
  return g;
 }
 function preview(key,id=selected().id,needId){const p=technologyProposal(project(),key,id,needId);if(!p){close(true);return bridge.toast('No missing support proposal is needed here. Review the current mappings or explore continuity.')}pause();proposal=p;close(true);simulation=null;view='all';bridge.state.visible=[...new Set([...bridge.state.visible,'physical','technology'])];bridge.state.selected=p.record.id||'t-ghost';bridge.state.focus=false;bridge.state.zoom=1;bridge.state.pan={x:0,y:0};bridge.setTab('model');bridge.toast('Unsaved technology proposal. Review, edit, or dismiss it.')}
 function editGhost(){if(proposal)dialog('Review proposal · '+proposal.record.title,capabilityForm({...proposal.record,mappings:proposal.mappings},true),'proposal')}
